from pathlib import Path
s=Path('research/shimos_worker_pool/integration_ab/prototype/vm.py').read_text()
s=s.replace("a.add_argument('--bad-export'", "a.add_argument('--variant',choices=['baseline_instrumented','ping_merged'],default='baseline_instrumented');a.add_argument('--requests',type=int,default=35);a.add_argument('--warmup',type=int,default=5);a.add_argument('--timing',choices=['0','1'],default='1');a.add_argument('--trace',choices=['0','1'],default='1');a.add_argument('--syscall-trace',action='store_true');a.add_argument('--bad-export'")
s=s.replace("choices=['runtime'", "choices=['performance','counter_state_corruption','counter_fd_leak','counter_forgotten_drop','counter_late_ack','counter_post_ack_controller_death','runtime'")
s=s.replace("proto=Path(__file__).resolve().parent;study=proto.parent;project=proto.parents[3]", "study=Path(__file__).resolve().parents[1];proto=study/args.variant;project=study.parents[2]")
s=s.replace("'exec python3 -B /state/cross-domain/prototype/run.py\\n'", "f'export COST_ENABLED={args.timing} COST_VARIANT={args.variant} COST_SESSION={args.name} COST_REQUESTS={args.requests} COST_WARMUP={args.warmup} COST_TRACE={args.trace} COST_SYSCALL_TRACE={int(args.syscall_trace)}\\n'+'exec python3 -B /state/cross-domain/prototype/run.py\\n'")
s=s.replace("'performance_benchmark':False", "'performance_benchmark':args.case=='performance','variant':args.variant,'timing':args.timing,'trace':args.trace,'requests':args.requests,'warmup':args.warmup")
s=s.replace("p.wait(timeout=180)","p.wait(timeout=300)")
s=s.replace("(out/'result.json').write_text", "manifest={'variant':args.variant,'source_sha256':json.loads((out/'source-sha.json').read_text()),'binary_sha256':{n:hashlib.sha256((out/n).read_bytes()).hexdigest() for n in ['bridge.so','native.so','domain_init','bridge_d.so','libab_probe.so'] if (out/n).exists()},'source_review_sha256':hashlib.sha256((study/'docs/variant-source-review.json').read_bytes()).hexdigest() if (study/'docs/variant-source-review.json').exists() else None}\n    (out/'variant-manifest.json').write_text(json.dumps(manifest,indent=2)+'\\n')\n    (out/'result.json').write_text")
Path('research/shimos_worker_pool/cost_breakdown/runner/vm.py').write_text(s)
